{
  "name": "goose-mcp",
  "version": "0.1.0",
  "description": "MCP server wrapping the goose CLI — sessions, recipes, providers, extensions",
  "author": "sandraschi",
  "license": "MIT",
  "homepage": "https://github.com/sandraschi/goose-mcp",
  "mcp": {
    "transport": ["stdio", "http"],
    "http_path": "/mcp"
  },
  "scripts": {
    "stdio": "uv run python -m goose_mcp.server",
    "http": "uv run python -m goose_mcp.api"
  }
}

# Per-repo fleet start config for goose-mcp
# Edit ports/backend target here - start.ps1 is fleet-standard.
@{
    Name         = 'goose-mcp'
    BackendPort  = 10948
    FrontendPort = 10949
    HealthPath   = '/api/health'
    WebRoot      = 'webapp'
    Backend = @{
        Kind          = 'uvicorn'
        UvicornTarget = 'goose_mcp.api:app'
        SyncExtras    = @('dev')
        SyncOnStart  = $true
        Env           = @{ WEB_PORT = '10948' }
    }
    Frontend = @{
        Kind           = 'vite-npm'
        PackageManager = 'npm'
        PortEnvVar     = 'VITE_PORT'
        ApiTargetEnv   = 'VITE_API_TARGET'
    }
}
